  html+='<li><h5>The numbers used</h5><ul class="b-assumptions">'+e.values.map(v=>{const or=ORIGIN[v.origin]||ORIGIN.toi;return '<li><span>'+esc(v.label)+' <i class="b-origin '+or[1]+'">'+(MV&&MV.usable(v.value)?or[0]:MV?MV.statusLabel(v.value):'')+'</i></span><b>'+esc(valueText(v.value,v.unit))+'</b>'+(v.field&&$(v.field)?btn('Edit','data-b-focus="'+esc(v.field)+'"'):'')+(v.text?'<small>'+esc(v.text)+'</small>':'')+'</li>';}).join('')+'</ul></li>';
