 function usageField(i,a,id){return field('assets.'+i+'.usage.perSession','It costs me every session ($)',a?.usage?.perSession,{id,hint:'Fuel, ammo, maintenance… your own number. Empty = not counted (never a made-up 0). Nothing is confirmed in GTA VI.'});}
 function capabilityFields(i,a,prefix){return '<div class="calc-fields">'+select('assets.'+i+'.capabilities.terrain','Where it can go (if you know)',CAP_TERRAIN,a?.capabilities?.terrain||'')+field('assets.'+i+'.capabilities.seats','Seats, you included (if you know)',a?.capabilities?.seats,{id:prefix+'-seats',integer:true,max:100})+'</div>';}
 function needStep(n){const need=state().analysis.need;return step(n,'What do you need it for?','<div class="calc-fields">'+select('analysis.need.terrain','Where it needs to go',TERRAIN_OPTS,need.terrain)+field('analysis.need.passengers','It needs to carry (people, you included)',need.passengers,{id:'need-passengers',integer:true,max:100,hint:'Leave empty if it doesn’t matter.'})+'</div>'+check('analysis.need.cargo','It needs to be able to carry stuff',need.cargo),'An option that doesn’t fit what you need it for is ruled out, even if it’s very fast or very cheap.');}
 function horizonField(id,label,hint){const h=state().analysis.horizon;return field('analysis.horizon.sessions',label||'I use it for (sessions)',h.sessions,{id,integer:true,max:10000,hint:hint||'Used to count the running cost over time. Empty = price only.'});}
 const SIMS=[['carburant','Fuel (vehicles)',[['distance','Distance per session (km)'],['consommation','Fuel use (liters per 100 km)'],['prixUnitaire','Price per liter ($)']]],['entretien','Maintenance (vehicles)',[['parPartie','Cost per session ($)']]],['reparation','Repairs (vehicles)',[['parPartie','Cost per session ($)']]],['assurance','Insurance (vehicles)',[['parPartie','Cost per session ($)']]],['munitions','Ammo (each mission attempt)',[['parTentative','Cost per attempt ($)']]],['echec','Failed attempts (My activities, My goal, My play time)',[['tentativesRatees','Failed attempts out of 10']]]];
 function hypothesesBlock(){const an=state().analysis;return '<details class="calc-optional b-hypotheses b-expert" id="calc-hypotheses"><summary>My assumptions: fuel, maintenance, ammo, failed attempts</summary><p class="calc-note"><b>Scope:</b> these assumptions count in the eight calculations. The business plan has its own fields; it only takes the simulated ammo, added to the fees of each mission attempt. None of these mechanics is confirmed in GTA VI: nothing is counted unless you choose it, and a chosen number stays marked “simulation” everywhere, even in your saved calculations. If you enter a purchase’s cost per session yourself, the simulation isn’t added to it.</p>'+SIMS.map(([k,label,fields])=>'<fieldset class="b-sim-item"><legend>'+check('analysis.simulations.'+k,label,an.simulations[k])+'</legend><div class="calc-fields" data-sim-fields="'+k+'" '+(an.simulations[k]?'':'hidden')+'>'+fields.map(([f,l])=>field('analysis.sim.'+k+'.'+f,l,an.sim[k][f],{id:'sim-'+k+'-'+f,max:k==='echec'?10:1e12,integer:k==='echec'})).join('')+'</div></fieldset>').join('')+'<p class="calc-note">Fuel: distance × fuel use ÷ 100 × price per liter = cost per session.</p></details>';}
 let plan=null;
 /* ===== v7.35 : « gros points » repliables. Tout ce qui n'est pas la réponse se lit en appuyant dessus.
    L'état (ouvert / fermé) est gardé sur l'appareil ; « Tout déplier » / « Tout replier » ; à l'impression tout s'ouvre. */
 const FOLD_KEY='lk-calc-folds-v1';let foldState={all:null,items:{}},foldForced=false,foldAnimate=null;
 try{const raw=localStorage.getItem(FOLD_KEY);if(raw){const v=JSON.parse(raw);if(v&&typeof v==='object'){foldState.all=v.all===true?true:v.all===false?false:null;foldState.items=v.items&&typeof v.items==='object'?v.items:{};}}}catch{}
 function foldPersist(){try{localStorage.setItem(FOLD_KEY,JSON.stringify(foldState));}catch{}}
 function foldIsOpen(id,def=false){if(foldForced)return true;if(foldState.all===true)return true;if(foldState.all===false)return false;const v=foldState.items[id];return typeof v==='boolean'?v:def;}
 function foldSet(id,open){foldState.items[id]=open;foldState.all=null;foldPersist();}
 function foldAll(open){foldState={all:open,items:{}};foldPersist();}
 /* fold(id, {n, title, teaser, body, open, kicker, tone}) : body est une chaîne ou une fonction (calculée seulement à l'ouverture). */
 function fold(id,o){const open=foldIsOpen(id,o.open===true);const body=open?(typeof o.body==='function'?o.body():o.body):'';
  return '<section class="b-fold'+(open?' is-open':'')+(o.tone?' b-fold--'+o.tone:'')+'" data-fold="'+esc(id)+'"><h3 class="b-fold-h"><button type="button" class="b-fold-head" data-fold-head="'+esc(id)+'" aria-expanded="'+open+'" aria-controls="fold-'+esc(id)+'"><span class="b-fold-num" aria-hidden="true">'+(o.n!==undefined?esc(String(o.n)):'<i></i>')+'</span><span class="b-fold-text"><span class="b-fold-title">'+esc(o.title)+'</span>'+(o.teaser?'<span class="b-fold-teaser">'+o.teaser+'</span>':'')+'</span><span class="b-fold-chevron" aria-hidden="true"></span></button></h3><div class="b-fold-body" id="fold-'+esc(id)+'"'+(open?'':' hidden')+'>'+body+'</div></section>';}
 /* Les résultats des huit outils : hypothèses, compromis et formules deviennent des points repliables, sans réécrire chaque outil. */
 function foldify(container,tool){if(!container)return;const doc=container.ownerDocument;let k=0;
  container.querySelectorAll('.b-fold').forEach(f=>{const open=foldIsOpen(f.dataset.fold,false);f.classList.toggle('is-open',open);const body=f.querySelector(':scope>.b-fold-body');if(body)body.hidden=!open;f.querySelector('.b-fold-head')?.setAttribute('aria-expanded',String(open));});
  const wrap=(node,id,title,teaser)=>{const sec=doc.createElement('div');sec.innerHTML=fold(id,{title,teaser,body:'',open:false});const f=sec.firstChild,body=f.querySelector('.b-fold-body');node.parentNode.insertBefore(f,node);body.appendChild(node);if(node.tagName==='DETAILS'){node.open=true;node.classList.add('b-fold-inner');}if(!foldIsOpen(id,false))body.hidden=true;else{body.hidden=false;f.classList.add('is-open');f.querySelector('.b-fold-head').setAttribute('aria-expanded','true');}};
  container.querySelectorAll(':scope .b-assumptions-box').forEach(node=>{if(node.closest('.b-fold'))return;if(node.dataset.teaser){wrap(node,tool+'-assumptions','What counts in this calculation',esc(node.dataset.teaser));return;}const items=[...node.querySelectorAll('.b-assumptions li')].slice(0,2).map(li=>(li.querySelector('span')?.textContent||'').replace(/\s+/g,' ').trim()+' '+(li.querySelector('b')?.textContent||'').trim()).join(' · ');const missing=node.querySelector('.b-missing');wrap(node,tool+'-assumptions','What counts in this calculation',esc(missing?'A number is missing · '+items:items));});
  container.querySelectorAll(':scope details').forEach(node=>{if(node.closest('.b-fold')||node.classList.contains('c-chart-data')||node.classList.contains('b-inline-activity')||node.classList.contains('calc-optional'))return;const sum=node.querySelector(':scope>summary');if(!sum)return;const title=sum.textContent.replace(/\s+/g,' ').trim();sum.hidden=true;wrap(node,tool+'-d'+(k++),title,node.dataset.teaser||(node.classList.contains('b-tradeoff')?'Compare the two choices':''));});}
 /* v7.59 (check ultime, D-01) : CSS.escape n’existe pas partout (anciens navigateurs, jsdom) ; sans garde, l’ouverture d’un point et les flèches de Quoi acheter d’abord ? levaient une erreur et la sauvegarde qui suivait n’avait pas lieu. */
 const cssEscape=v=>typeof CSS!=='undefined'&&typeof CSS.escape==='function'?CSS.escape(v):String(v).replace(/[^a-zA-Z0-9_-]/g,c=>'\\'+c);
 function foldAfterRender(){if(!foldAnimate)return;const f=document.querySelector('[data-fold="'+cssEscape(foldAnimate)+'"]');foldAnimate=null;if(!f)return;const body=f.querySelector('.b-fold-body');if(body&&!body.hidden){body.classList.add('is-anim');body.addEventListener('animationend',()=>body.classList.remove('is-anim'),{once:true});}if(f.getBoundingClientRect().top<(document.querySelector('header')?.getBoundingClientRect().bottom||0))f.scrollIntoView({block:'start',behavior:'smooth'});}
 function panel(id,title,form,result){return '<section class="calc-panel" id="panel-'+id+'" role="tabpanel" aria-labelledby="tab-'+id+'" hidden><div class="calc-grid"><div class="calc-card"><p class="calc-kicker">'+esc(B.names[id])+'</p><h3>'+esc(title)+'</h3>'+form+'</div><div class="calc-card calc-result" id="'+result+'"></div></div></section>';}
 function compareItems(){const s=state();if(!s.compare.keys.length)return '<p class="calc-empty">Add two or more purchases to compare them.</p>';return s.compare.keys.map((key,index)=>{const a=lookup(key);if(!a)return '';const i=s.assets.indexOf(a),item=itemFor(a);return '<article class="b-order-item b-compare-item" data-b-compare-key="'+esc(key)+'"><div class="b-order-head">'+media(item)+'<div><strong>'+esc((index+1)+'. '+a.name)+'</strong><p>'+esc(labels[item?.type]||'Custom purchase')+' · '+(a.price===null?'price not known yet':money(a.price+a.extras+a.fees))+'</p></div></div><div class="calc-fields">'+(!a.itemId?field('assets.'+i+'.name','Name of this purchase',a.name,{type:'text',id:'compare-name-'+index}):'')+priceField(key,'compare-price-'+index)+select('assets.'+i+'.utility','How much I want it (1 to 5, optional)',[['','— not rated'],['1','1 · meh'],['2','2 · why not'],['3','3 · I’d like it'],['4','4 · I really want it'],['5','5 · it’s my dream']],a.utility===null||a.utility===undefined?'':String(a.utility))+usageField(i,a,'compare-usage-'+index)+'</div><div class="b-expert calc-fields">'+select('assets.'+i+'.incomeMode','Does this purchase make me money?',[['none','No, it’s just for fun'],['personal','Yes, about this much per hour (I’ll enter it)'],['roi','Yes, what “Is it worth it?” says']],a.incomeMode)+field('assets.'+i+'.boostHourly','It earns me extra ($ per hour)',a.boostHourly,{id:'compare-boost-'+index})+'</div>'+(!item||item.type==='vehicle'?'<details class="calc-optional"><summary>Its capabilities, if you know them</summary>'+capabilityFields(i,a,'compare-cap-'+index)+'<p class="calc-note">The site doesn’t know the seats or terrain of GTA VI vehicles; without your answer: “to check”.</p></details>':'')+'<div class="b-order-actions">'+btn('Remove','data-b-compare-remove="'+esc(key)+'"')+'</div></article>';}).join('');}
 function planMarkup(){return plan.markup();}
 function ensurePlan(){if(!plan)plan=global.LKCalcPlan.create({esc,money,hours,field,stats,warning,btn,select,table,lookup,itemFor,selectedCard,combobox,step,refresh,state,sourceActivities,visual,api,decision,problem,fold,foldIsOpen,explainBlock,analysisOf});return plan;}
