 const roi=panel('roi','Is it worth it?',
 '<div class="calc-fields calc-steps">'+step(1,'Which purchase?',combobox('roi-search','Which purchase? (search the site)','roi')+btn('Enter a custom purchase','data-b-roi-manual="1"')+'<div id="roi-selection">'+selectedCard(a)+'</div>'+(!a.itemId?field('assets.'+i+'.name','Name of my purchase',a.name,{type:'text',id:'roi-name'}):''))+
 step(2,'Can I afford it?','<div class="calc-fields">'+priceField(r.key,'f-roi-purchase')+field('goal.capital','I already have ($)',s.goal.capital,{id:'roi-capital'})+field('goal.reserve','Money I set aside ($)',s.goal.reserve,{id:'roi-reserve'})+'</div>')+
 step(3,'Why this purchase? ',select('roi.mode','What this purchase changes for me',[['estimate','Just for fun, or I don’t know what it brings in'],['new','Without it, I can’t do these activities'],['improve','With it, these activities pay more'],['continuous','I know how much extra it earns me, per hour']],r.mode)+'<div id="roi-links">'+roiLinks()+'</div>'+field('roi.hours','I use it for (hours of play)',r.hours,{max:16666})+'<div class="calc-fields">'+field('roi.gainPercent','Extra reward (%)',r.gainPercent,{max:1000,hint:'Only what the purchase earns you on top.'})+field('roi.durationReduction','Mission shorter by (%)',r.durationReduction,{max:95})+'</div>')+'</div>'+
 '<details class="calc-optional"><summary>Compare two purchases with the same budget</summary>'+combobox('roi-compare-search','Other purchase to compare (optional)','roi-compare')+btn('Compare with a custom purchase','data-b-roi-alternative="1"')+(alternative?selectedCard(alternative)+(!alternative.itemId?field('assets.'+s.assets.indexOf(alternative)+'.name','Name of the second purchase',alternative.name,{type:'text',id:'roi-alternative-name'}):'')+priceField(alternative.key,'roi-alternative-price')+btn('Remove this comparison','data-b-roi-remove-comparison="1"'):'')+'<p class="calc-note">Same starting money, same money set aside, same play time. Which one you want more, only you know.</p></details>'+
 '<details class="calc-optional"><summary>Options, upfront fees, running cost and resale</summary><div class="calc-fields">'+field('assets.'+i+'.extras','Upgrades ($)',a?.extras,{id:'f-roi-upgrades'})+field('assets.'+i+'.fees','Other required upfront fees ($)',a?.fees,{id:'f-roi-fees'})+usageField(i,a,'f-roi-usage')+field('assets.'+i+'.resale','I could resell it for ($, my guess)',a?.resale,{id:'f-roi-resale',hint:'Resale isn’t confirmed in GTA VI. It lowers the future cost, never the money to pay today.'})+'</div></details><p class="calc-note">The price, your money and your activities are the same in every tool. You can enter everything here, without making a plan.</p>','roi-results');
 const budget=panel('budget','Do I have enough money?', '<p class="calc-note">Enter your expenses yourself, or bring in your purchases from “What should I buy first?” if you have any.</p><div class="calc-fields calc-steps">'+step(1,'How much do you have?','<div class="calc-fields">'+field('goal.capital','I already have ($)',s.goal.capital,{id:'budget-capital'})+field('goal.reserve','Money I set aside ($)',s.goal.reserve,{id:'budget-reserve'})+'</div>')+step(2,'Which purchases should count?',select('budget.source','Which purchases should count?',[['manual','I split it myself'],['basket','My purchases from “What should I buy first?”']],s.budget.source)+'<div id="budget-manual" '+(s.budget.source==='manual'?'':'hidden')+'><fieldset class="b-budget-split"><legend>Your split: every line counts, all are shown</legend><div class="calc-fields">'+['Vehicles','Investments','Gear','Consumables','Other purchases'].map((n,i)=>field('budget.allocations.'+i,n+' ($)',s.budget.allocations[i])).join('')+'</div></fieldset></div>')+step(3,'Any other expenses?',field('budget.extra','Other planned expenses ($)',s.budget.extra))+'</div>'+'<div class="b-expert">'+horizonField('budget-sessions','Over how many sessions do you want to see your money?','Each session: what you earn per hour × your time per day, minus the running cost of your purchases.')+'</div>'+btn('See my purchases','data-open="order"'),'budget-results');
 const order=panel('order','What should I buy first?','<div class="calc-fields calc-steps">'+step(1,'How much do you have?','<div class="calc-fields">'+field('goal.capital','I already have ($)',s.goal.capital,{id:'order-capital'})+field('goal.reserve','Money I set aside ($)',s.goal.reserve,{id:'order-reserve'})+field('goal.hourly','I earn about ($ per hour), if I have to wait',s.goal.hourly,{id:'order-hourly'})+'</div>')+step(2,'What do you want to buy?',combobox('order-search','Add a purchase (search the site)','order')+btn('Add something else, without a page','data-b-add-free="1"'))+step(3,'What matters to you',select('order.objective','I want',[['all','Get everything as fast as possible'],['income','Get a money-making purchase as early as possible'],['reserve','Keep the most money at each step'],['given','Keep my own order']],s.order.objective),'The calculator tries the possible orders and keeps the best one for what you want; it also shows you your own order.')+'</div><p class="calc-note" id="order-capital-summary"></p><div id="order-items">'+orderItems()+'</div><p class="calc-note">The arrows change the order without losing the prices. Earnings tied to a purchase start after you pay for it.</p>','order-results');
 const compare=panel('compare','Which purchase should I pick?','<div class="calc-fields calc-steps">'+step(1,'Which purchases do you want to compare?',combobox('compare-search','Add a purchase (search the site)','compare')+btn('Add a custom purchase','data-b-compare-free="1"')+'<div id="compare-items">'+compareItems()+'</div>')+step(2,'How much do you have?','<div class="calc-fields">'+field('goal.capital','I already have ($)',s.goal.capital,{id:'compare-capital'})+field('goal.reserve','Money I set aside ($)',s.goal.reserve,{id:'compare-reserve'})+field('goal.hourly','I earn about ($ per hour), if I have to wait',s.goal.hourly,{id:'compare-hourly'})+field('goal.dailyMinutes','Time I play per day (minutes)',s.goal.dailyMinutes,{id:'compare-daily',max:1440})+'</div>')+needStep(3)+step(4,'What matters most to you',select('compare.criterion','What I want most',[['value','The best want score for the price'],['cheapest','The cheapest to buy'],['cheapestTotal','The cheapest over time (price + use)'],['fastest','The one I can get the fastest'],['profit','The one that pays for itself the fastest'],['utility','The one I want the most']],s.compare.criterion)+'<div id="compare-horizon">'+horizonField('compare-sessions','I use it for (sessions)','For “the cheapest over time”: each option’s running cost is counted over this number of sessions.')+'</div><div class="b-expert">'+field('compare.hours','I use it for (hours of play)',s.compare.hours,{id:'compare-hours',max:16666})+'</div>')+'</div><p class="calc-note">The want score is your rating from 1 to 5. A purchase only earns money if you enter what it earns. Nothing comes from the actual game.</p>','compare-results');
