 function orderItems(){const s=state();if(!s.order.keys.length)return '<p class="calc-empty">Add your first purchase. A missing price stays unknown.</p>';return s.order.keys.map((key,index)=>{const a=lookup(key);if(!a)return warning('Purchase not found: '+key)+btn('Stop comparing','data-b-order-remove="'+esc(key)+'"');const i=s.assets.indexOf(a),item=itemFor(a);return '<article class="b-order-item" data-b-order-key="'+esc(key)+'"><div class="b-order-head">'+media(item)+'<div><strong>'+esc((index+1)+'. '+a.name)+'</strong><p>'+esc(labels[item?.type]||'Custom purchase')+' · '+orderPrice(a)+'</p></div></div><div class="b-order-actions">'+btn('↑','data-b-order-up="'+esc(key)+'" aria-label="Move up '+esc(a.name)+'" '+(index===0?'disabled':''))+btn('↓','data-b-order-down="'+esc(key)+'" aria-label="Move down '+esc(a.name)+'" '+(index===s.order.keys.length-1?'disabled':''))+btn('Edit','data-b-order-edit="'+esc(key)+'" aria-expanded="'+(orderEditor===key)+'"')+btn('Remove','data-b-order-remove="'+esc(key)+'"')+'</div><div '+(orderEditor===key?'':'hidden')+' class="b-order-editor">'+(!a.itemId?field('assets.'+i+'.name','Name of this purchase',a.name,{type:'text'}):'')+priceField(key,'order-price-'+index)+'<div class="b-expert">'+field('assets.'+i+'.extras','Fees and upgrades ($)',a.extras)+field('assets.'+i+'.fees','Other upfront fees ($)',a.fees)+select('assets.'+i+'.incomeMode','What I earn after this purchase',[['none','No extra income'],['personal','Yes, about this much per hour (I’ll enter it)'],['roi','Linked result from “Is it worth it?”']],a.incomeMode)+field('assets.'+i+'.boostHourly','It earns me extra ($ per hour)',a.boostHourly,{hint:'Only if this money really adds to what you already earn. The game promises nothing.'})+'<label class="calc-check"><input type="checkbox" data-b-owned="'+esc(key)+'" '+(a.owned?'checked':'')+'> Purchase already owned (activity requirement met)</label>'+usageField(i,a,'order-usage-'+index)+(s.order.keys.length>1?'<fieldset class="b-requires"><legend>To buy before it (if required)</legend>'+s.order.keys.filter(k=>k!==key).map(k=>{const o=lookup(k);return o?'<label class="calc-check"><input type="checkbox" data-b-requires="'+esc(key)+'|'+esc(k)+'" '+((a.requires||[]).includes(k)?'checked':'')+'> '+esc(o.name)+'</label>':'';}).join('')+'<p class="calc-note">Only check this if the game really requires it (for example, an upgrade that needs the vehicle). The suggested order will respect it.</p></fieldset>':'')+'</div></div></article>';}).join('')+(lastRemoved?btn('Undo removing from the cart','data-b-order-undo="1"'):'');}
