 document.querySelectorAll('.b-expert input[data-number],.calc-advanced input[data-number]').forEach(el=>{const path=el.dataset.field;if(!path)return;let ref=api.initial;for(const k of path.split('.'))ref=ref?.[k];if(path.startsWith('assets.')&&ref===undefined)ref=path.endsWith('extras')||path.endsWith('fees')||path.endsWith('boostHourly')?0:null;if(ref===undefined)return;el.closest('.calc-field').insertAdjacentHTML('beforeend','<small>Default value: '+esc(ref===null?'unknown':nf.format(ref))+'</small><button type="button" class="calc-text-button" data-b-default="'+esc(path)+'" data-b-default-value="'+esc(ref===null?'null':ref)+'">Restore this value</button>');});
