     assumptions:base.concat([{label:'Extra earnings',value:money(s.roi.revenueHourly)+'/h',origin:'toi',field:'f-roi-revenueHourly'},{label:'Extra cost',value:money(s.roi.costHourly)+'/h',origin:'toi',field:'f-roi-costHourly'},{label:'Time you use it',value:hours(H),origin:'toi',field:'f-roi-hours'}].concat(c.baselineHourly!==null?[{label:'What you were already earning',value:money(c.baselineHourly)+'/h',origin:'toi',field:'f-goal-hourly'}]:[])),
