    const cols=[['','Without the purchase','With the purchase'],['I pay up front',money(0),money(r.investment)],['What it earns over '+hours(H)+', minus mission fees',known&&!improve?money(r.opportunityCost):improve?money(r.beforeNet):'—',known&&!improve?money(r.operatingProfit):improve?money(r.afterNet):money(r.operatingProfit)],['Difference, minus the price','',money(net)]];
