  if(t==='roi')return [['Purchase',a?.name||'not chosen'],['Price',cash(a?.price)],['Over',hours(s.roi.hours)+' of play']];
  if(t==='compare')return [['Purchases compared',nf.format(s.compare.keys.length)],['What I want most',CRITERIA[s.compare.criterion]||'not chosen'],['I have',cash(g.capital)]];
