  document.querySelectorAll('[data-b-pick]').forEach(i=>{i.checked=picked.includes(i.dataset.bPick);i.closest('.b-notebook-entry')?.classList.toggle('is-picked',i.checked);});
  if(comparing&&picked.length!==2)comparing=false;
